		/// Creates a duplicate of the current <see cref="EntityDescriptorPropertiesSection"/> with a new id.
		/// </summary>
		/// <returns>A new <see cref="EntityDescriptorPropertiesSection"/> object that is a copy of this section but with a different id.</returns>
		public EntityDescriptorPropertiesSection Duplicate()
		{
			var section = (Section)this.ToSection().Clone();
			section.ID = new SectionID(Guid.NewGuid());
			return new EntityDescriptorPropertiesSection(section);
		}
	}
}
